// Fuentes RSS. Para añadir o quitar una, edita esta lista.
// "id" es lo que se guarda en raw_news.source.
const fuentes = [
  { id: 'ahead_of_ai',      url: 'https://magazine.sebastianraschka.com/feed' },
  { id: 'import_ai',        url: 'https://importai.substack.com/feed' },
  { id: 'latent_space',     url: 'https://www.latent.space/feed' },
  { id: 'simon_willison',   url: 'https://simonwillison.net/atom/everything/' },
  { id: 'one_useful_thing', url: 'https://www.oneusefulthing.org/feed' },
  { id: 'openai_news',      url: 'https://openai.com/news/rss.xml' },
  { id: 'n8n_releases',     url: 'https://github.com/n8n-io/n8n/releases.atom' },
];
// Solo feeds que traen texto: con el titular solo, la IA no tiene de dónde resumir.
return fuentes.map(f => ({ json: f }));

// Convierte cada entrada del feed en una fila de raw_news.
// Solo entra lo publicado en los últimos DIAS días y con fecha: una noticia sin fecha
// no se puede filtrar por periodo y no se guarda. Máximo MAX_POR_FUENTE por fuente.
const DIAS = 7;
const MAX_POR_FUENTE = 15;
const MAX_TEXTO = 1500;

const ahora = Date.now();
const desde = ahora - DIAS * 864e5;
const limpiar = (s) => String(s ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ').trim();

const porFuente = {};
const vistas = new Set();

$input.all().forEach((item, i) => {
  const fuente = $('Fuentes').itemMatching(i).json.id;
  const e = item.json;
  if (e.error) return; // feed caído: se ignora y siguen los demás

  const url = String(e.link || e.guid || '').trim();
  if (!/^https?:\/\//.test(url) || vistas.has(url)) return;

  const t = Date.parse(e.isoDate || e.pubDate || '');
  if (Number.isNaN(t) || t < desde || t > ahora + 864e5) return;

  const titulo = limpiar(e.title).slice(0, 500);
  if (!titulo) return;

  vistas.add(url);
  (porFuente[fuente] ||= []).push({
    title: titulo,
    url,
    source: fuente,
    published_at: new Date(t).toISOString(),
    raw_content: limpiar(e.contentSnippet || e.summary || e.content || '').slice(0, MAX_TEXTO),
  });
});

return Object.values(porFuente)
  .flatMap(filas => filas
    .sort((a, b) => b.published_at.localeCompare(a.published_at))
    .slice(0, MAX_POR_FUENTE))
  .map(fila => ({ json: fila }));
